<section class="card"><div class="card-header"><div><h2>پرونده‌ها و بررسی‌های حقوقی</h2><p class="text-muted"><?= to_persian_digits($result['total'] ?? 0) ?> پرونده</p></div></div><div class="table-wrap"><table><thead><tr><th scope="col">شماره پرونده</th><th scope="col">قرارداد</th><th scope="col">مرحله</th><th scope="col">وکیل</th><th scope="col">وضعیت</th><th scope="col">آخرین تغییر</th></tr></thead><tbody><?php foreach (($result['items'] ?? []) as $case): ?><tr><td><?= e($case['complaint_number'] ?: ('#' . (int) $case['id'])) ?></td><td><?= e($case['contract_number'] ?? '') ?></td><td><?= e($case['stage'] ?? '') ?></td><td><?= e($case['lawyer_name'] ?? 'تخصیص‌نیافته') ?></td><td><?= e($case['status'] ?? '') ?></td><td><?= e(jdatetime($case['updated_at'] ?? '')) ?></td></tr><?php endforeach; ?><?php if (empty($result['items'])): ?><tr><td colspan="6" class="empty">پرونده حقوقی ثبت نشده است.</td></tr><?php endif; ?></tbody></table></div><?php require __DIR__ . '/_pagination.php'; ?></section>
